scwin.scbScript = undefined; try { scwin.scbScript = /* sdd-asis-lifecycle:begin scbScript — as-is 원문 본문(전환 이관 · 포팅 적용됨) */document.createElement('script')/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf10004' }); }

